from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 1 and (r, c) not in seen:
                q = [(r, c)]
                seen.add((r, c))
                comp = []
                while q:
                    y, x = q.pop()
                    comp.append((y, x))
                    for dy in (-1,0,1):
                        for dx in (-1,0,1):
                            if dy == 0 and dx == 0: continue
                            yy, xx = y + dy, x + dx
                            if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 1 and (yy, xx) not in seen:
                                seen.add((yy, xx))
                                q.append((yy, xx))
                    continue
                    for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        yy, xx = y + dy, x + dx
                        if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 1 and (yy, xx) not in seen:
                            seen.add((yy, xx))
                            q.append((yy, xx))
                comps.append(comp)
    shape = max(comps, key=len)
    r0, r1 = min(r for r,c in shape), max(r for r,c in shape)
    c0, c1 = min(c for r,c in shape), max(c for r,c in shape)
    pattern = {(r-r0, c-c0) for r,c in shape}
    # Find the compact repeated-row color key among the other components.
    shape_set = set(shape)
    seen2 = set()
    others = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and (r,c) not in shape_set and (r,c) not in seen2:
                q = [(r,c)]
                seen2.add((r,c))
                comp = []
                while q:
                    y,x = q.pop()
                    comp.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        yy,xx=y+dy,x+dx
                        if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 0 and (yy,xx) not in shape_set and (yy,xx) not in seen2:
                            seen2.add((yy,xx)); q.append((yy,xx))
                others.append(comp)
    key = min(others, key=len)
    kr0, kr1 = min(r for r,c in key), max(r for r,c in key)
    kc0, kc1 = min(c for r,c in key), max(c for r,c in key)
    colors = [grid[kr0][c] for c in range(kc0, kc1+1)]
    center = colors.index(1)
    sh, sw = r1-r0+1, c1-c0+1
    out = [[0 for _ in range(w)] for _ in range(h)]
    for i, color in enumerate(colors):
        top = r0 + (i-center)*sh
        for dr, dc in pattern:
            rr, cc = top+dr, c0+dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out
